// A loader in the shape wasm-bindgen's web target generates: the module's
// wrapper classes register with a FinalizationRegistry when they are
// created and unregister when free() releases them, and a TextEncoder
// polyfill guard runs at load.
let wasm;
const cachedTextEncoder = new TextEncoder();
if (!("encodeInto" in cachedTextEncoder)) {
  cachedTextEncoder.encodeInto = function (arg, view) {
    const buf = cachedTextEncoder.encode(arg);
    view.set(buf);
    return { read: arg.length, written: buf.length };
  };
}
let released = 0;
const CounterFinalization =
  typeof FinalizationRegistry === "undefined"
    ? { register: () => {}, unregister: () => {} }
    : new FinalizationRegistry((ptr) => wasm.add(ptr >>> 0, 1));

export class Counter {
  static __wrap(ptr) {
    const obj = Object.create(Counter.prototype);
    obj.__wbg_ptr = ptr;
    CounterFinalization.register(obj, obj.__wbg_ptr, obj);
    return obj;
  }
  constructor(start) {
    this.__wbg_ptr = wasm.add(start, 0);
    CounterFinalization.register(this, this.__wbg_ptr, this);
  }
  __destroy_into_raw() {
    const ptr = this.__wbg_ptr;
    this.__wbg_ptr = 0;
    CounterFinalization.unregister(this);
    return ptr;
  }
  free() {
    const ptr = this.__destroy_into_raw();
    released += wasm.add(ptr, 0);
  }
  increment(by) {
    this.__wbg_ptr = wasm.add(this.__wbg_ptr, by);
    return this.__wbg_ptr;
  }
  get value() {
    return this.__wbg_ptr;
  }
}
if (Symbol.dispose) Counter.prototype[Symbol.dispose] = Counter.prototype.free;

export function released_total() {
  return released;
}

export function initSync(bytes) {
  if (wasm !== undefined) return wasm;
  const module = new WebAssembly.Module(bytes);
  const instance = new WebAssembly.Instance(module, {});
  wasm = instance.exports;
  return wasm;
}
